{
  "includeCoAuthoredBy": false,
  "attribution": {
    "commit": "",
    "pr": ""
  },
  "autoMemoryEnabled": false,
  "claudeMdExcludes": [
    "/Users/alex-example/CLAUDE.md",
    "/Users/alex-example/CLAUDE.local.md",
    "/Users/alex-example/.claude/CLAUDE.md",
    "/Users/CLAUDE.md",
    "/Users/CLAUDE.local.md",
    "/Users/.claude/CLAUDE.md",
    "/CLAUDE.md",
    "/CLAUDE.local.md",
    "/.claude/CLAUDE.md"
  ],
  "sandbox": {
    "enabled": true,
    "failIfUnavailable": true,
    "allowUnsandboxedCommands": false,
    "autoAllowBashIfSandboxed": true,
    "network": {
      "allowedDomains": [
        "registry.example.com"
      ],
      "strictAllowlist": true,
      "allowUnixSockets": [
        "//Users/alex-example/.gnupg/S.gpg-agent"
      ]
    },
    "filesystem": {
      "allowWrite": [
        "//Users/alex-example/hatch/J1",
        "//Users/alex-example/example-write"
      ],
      "denyWrite": [
        "//Users/alex-example/example-repository/.example-data"
      ],
      "denyRead": [
        "//Users/alex-example/.ssh"
      ]
    }
  },
  "permissions": {
    "allow": [
      "Read",
      "Agent",
      "Edit(//Users/alex-example/example-repository/.example-worktrees/ticket-7/**)",
      "Write(//Users/alex-example/example-repository/.example-worktrees/ticket-7/**)",
      "Bash(uv *)",
      "Bash(git commit *)",
      "WebFetch(domain:registry.example.com)"
    ],
    "deny": [
      "Edit(//Users/alex-example/example-repository/.example-data)",
      "Edit(//Users/alex-example/example-repository/.example-data/**)",
      "Write(//Users/alex-example/example-repository/.example-data)",
      "Write(//Users/alex-example/example-repository/.example-data/**)",
      "Read(//Users/alex-example/.ssh)",
      "Read(//Users/alex-example/.ssh/**)",
      "Bash(git push *)"
    ]
  }
}

